import json

import numpy as np
from mlxtend.evaluate import feature_importance_permutation as fip

rs = np.random.RandomState(7)
X0 = rs.normal(size=(30, 4))
W = np.array([2.0, -1.0, 0.5, 0.25])
Y = X0 @ W


def predict(X):
    return X @ W


def columns_touched(groups):
    seen = []

    def pm(Z):
        seen.append([int(c) for c in range(X0.shape[1]) if not np.array_equal(Z[:, c], X0[:, c])])
        return predict(Z)
    try:
        fip(X0.copy(), Y, pm, metric="r2", num_rounds=1, seed=1, feature_groups=groups)
    except Exception as e:  # noqa: BLE001
        return {"raises": type(e).__name__}
    return seen[1:]


def importances(groups):
    try:
        mean, _ = fip(X0.copy(), Y, predict, metric="r2", num_rounds=2, seed=1, feature_groups=groups)
    except Exception as e:  # noqa: BLE001
        return {"raises": type(e).__name__}
    return [round(float(v), 8) for v in mean]


obs = {
    "list_groups.columns_touched": columns_touched([[1], [2], [3]]),
    "range_group.columns_touched": columns_touched([0, range(2, 4)]),
    "int_groups.importances": importances([0, 1, 2, 3]),
}
print(json.dumps({"observations": obs}, sort_keys=True))
